command:example.dev:code:
# Exporteer en vergelijk met vorige back-up
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Nieuwe scripts: $($new.Count) | Verwijderde scripts: $($removed.Count)"

dev:remarks.maml:para:
Haalt de opgeloste cachemap op. `Cache.Path` blijft de optionele, door de gebruiker geconfigureerde override;
`Cache.EffectivePath` toont de map die de module daadwerkelijk gebruikt na de standaardinstellingen van het platform en
omgevingsoverschrijvingen worden toegepast.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Aangepast cachepad geconfigureerd: $($config.Cache.Path)"
} else {
    Write-Host "Standaardcachepad wordt gebruikt"
}

Write-Host "Effectief cachepad: $($config.Cache.EffectivePath)"

# Bouw cache voor gefilterde scripts
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Zoek het eerste script dat overeenkomt met een patroon voor snelle weergave
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Controleer of alle scripts waarnaar wordt verwezen bestaan voordat u de automatisering uitvoert
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Ontbrekende scripts: $($missing -join ', ')"
} else {
    Write-Host "Alle vereiste scripts zijn beschikbaar"
}

# Maak meerdere colorscripts voor een project
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "$($scriptNames.Count) colorscript-sjablonen gemaakt"

# Controleer de naamconventies van scripts
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Ongeldige naam '$name': $_"
    }
}

# Creëer met categorie- en tagvalidatie
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "Categorie Retro niet gevonden"
}

# Controleer of het resetten is gelukt
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "Configuratie teruggezet naar de platformstandaard"
} else {
    Write-Host "Configuratie teruggezet, maar er wordt een aangepast pad gebruikt: $($config.Cache.Path)"
}

# Maak een diavoorstelling van de geometrische colorscripts
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Voorbeeld van foutafhandeling
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Script niet gevonden: $_"
    Show-ColorScript  # Terugval op willekeurig
}

# Bouw automatiseringsintegratie
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Willekeurige weergave voor interactief gebruik
}

# Geplande taak voor terminalbegroeting
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
